import{_ as o,o as t,c as d,a3 as a}from"./chunks/framework.CezWKtOZ.js";const u=JSON.parse('{"title":"API 稳定性","description":"","frontmatter":{},"headers":[],"relativePath":"api-stability.md","filePath":"api-stability.md","lastUpdated":1795881530000}'),c={name:"api-stability.md"};function i(r,e,n,l,s,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="api-稳定性" tabindex="-1">API 稳定性 <a class="header-anchor" href="#api-稳定性" aria-label="Permalink to &quot;API 稳定性&quot;">​</a></h1><p>LiteGUI 使用 <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>：</p><ul><li><strong>patch</strong>：修复 bug、内部重构、文档；</li><li><strong>minor</strong>：新增组件/选项、向后兼容的行为调整；</li><li><strong>major</strong>：删除或重命名公共 API、改变默认行为。</li></ul><h2 id="stable" tabindex="-1">Stable <a class="header-anchor" href="#stable" aria-label="Permalink to &quot;Stable&quot;">​</a></h2><p>以下 API 在 1.0 前尽量保持兼容：</p><p><code>Area</code>、<code>Panel</code>、<code>Split</code>、<code>Tabs</code>、<code>Dialog</code>、<code>Menu</code>、<code>Button</code>、<code>Checkbox</code>、<code>Slider</code>、<code>SearchBox</code>、<code>List</code>、<code>Table</code>、<code>Console</code>，以及 <code>LiteGUI.init/add/remove/bind/unbind/trigger/setTheme/getTheme/escapeHTML</code>。</p><p>约定：</p><ul><li>组件暴露 <code>root: HTMLElement</code>；</li><li>值类组件提供 <code>getValue()</code> / <code>setValue()</code>；</li><li>构造函数优先接收 options 对象；</li><li>样式通过 <code>@gausszhou/litegui-components/style.css</code> 或子路径 <code>@gausszhou/litegui-components/&lt;component&gt;</code> 引入。</li></ul><h2 id="experimental" tabindex="-1">Experimental <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;Experimental&quot;">​</a></h2><p><code>Inspector</code>、<code>Tree</code>、<code>ContextMenu</code>、<code>Dragger</code>、<code>LineEditor</code>、<code>ComplexList</code>、<code>Viewport</code> 暂不承诺 API 稳定，可能在 minor 版本调整。</p><h2 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to &quot;Deprecated&quot;">​</a></h2><p>以下写法会输出一次性 <code>console.warn</code>，并计划在 1.0 前移除或转为正式 API：</p><table tabindex="0"><thead><tr><th>写法</th><th>替代</th></tr></thead><tbody><tr><td><code>new Area(id, options)</code></td><td><code>new Area(options)</code></td></tr><tr><td><code>new Tabs(id, options)</code></td><td><code>new Tabs(options)</code></td></tr><tr><td><code>new Tree(id, data, options)</code></td><td><code>new Tree(data, options)</code></td></tr><tr><td><code>new Inspector(id, options)</code></td><td><code>new Inspector(options)</code></td></tr><tr><td><code>new Dialog(id)</code></td><td><code>new Dialog({ id })</code></td></tr><tr><td><code>dialog.setPositon(x, y)</code></td><td><code>dialog.setPosition(x, y)</code></td></tr><tr><td><code>LiteGUI.craeteDivElement(...)</code></td><td><code>LiteGUI.createElement(...)</code></td></tr></tbody></table><h2 id="_1-0-前的检查项" tabindex="-1">1.0 前的检查项 <a class="header-anchor" href="#_1-0-前的检查项" aria-label="Permalink to &quot;1.0 前的检查项&quot;">​</a></h2><ul><li>移除 <code>@ts-nocheck</code>（Inspector/Tree/ContextMenu）或明确降级为独立包；</li><li>统一 <code>mount/destroy</code> 生命周期；</li><li>完成焦点管理与键盘导航；</li><li>补 Playwright 视觉回归和浏览器矩阵；</li><li>冻结导出表与 <code>exports</code> 子路径。</li></ul>',15)])])}const m=o(c,[["render",i]]);export{u as __pageData,m as default};
